import { readFileSync } from 'node:fs';
import { pathToFileURL } from 'node:url';

const compare = (a, b) => a < b ? -1 : a > b ? 1 : 0;
const validId = id => typeof id === 'string' && id.length > 0;

// Newly available IDs must compete immediately with every queued ID.
class MinHeap {
  items = [];

  push(id) {
    const items = this.items;
    let index = items.length;
    items.push(id);
    while (index > 0) {
      const parent = Math.floor((index - 1) / 2);
      if (items[parent] <= id) break;
      items[index] = items[parent];
      index = parent;
    }
    items[index] = id;
  }

  pop() {
    const items = this.items;
    const first = items[0];
    const last = items.pop();
    if (items.length === 0) return first;
    let index = 0;
    while (index * 2 + 1 < items.length) {
      let child = index * 2 + 1;
      if (child + 1 < items.length && items[child + 1] < items[child]) child++;
      if (last <= items[child]) break;
      items[index] = items[child];
      index = child;
    }
    items[index] = last;
    return first;
  }
}

export function planJobs(spec) {
  if (!Array.isArray(spec)) throw new Error('Expected an array of jobs');
  const jobs = new Map();
  for (const job of spec) {
    if (job === null || typeof job !== 'object' || Array.isArray(job)) {
      throw new Error('Expected a job object');
    }
    const { id, deps, state } = job;
    if (!validId(id) || !Array.isArray(deps) ||
        !['pending', 'succeeded', 'failed'].includes(state)) {
      throw new Error('Invalid job fields');
    }
    if (jobs.has(id)) throw new Error(`Duplicate job ID: ${id}`);
    const dependencies = new Set();
    for (const dep of deps) {
      if (!validId(dep)) throw new Error(`Invalid dependency for: ${id}`);
      if (dependencies.has(dep)) throw new Error(`Duplicate dependency for: ${id}`);
      dependencies.add(dep);
    }
    jobs.set(id, { id, deps: [...dependencies], state, children: [],
      indegree: dependencies.size, causes: new Set() });
  }

  const available = new MinHeap();
  for (const job of jobs.values()) {
    for (const dep of job.deps) {
      if (!jobs.has(dep)) throw new Error(`Unknown dependency: ${dep}`);
      jobs.get(dep).children.push(job.id);
    }
    if (job.indegree === 0) available.push(job.id);
  }

  const topology = [];
  while (available.items.length > 0) {
    const id = available.pop();
    const job = jobs.get(id);
    topology.push(id);
    for (const childId of job.children) {
      const child = jobs.get(childId);
      // Carry failed ancestry through succeeded and failed intermediates too.
      for (const cause of job.causes) child.causes.add(cause);
      if (job.state === 'failed') child.causes.add(id);
      if (--child.indegree === 0) available.push(childId);
    }
  }
