import test from 'node:test';
import assert from 'node:assert/strict';
import { mkdtempSync, writeFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { spawnSync } from 'node:child_process';
import { planJobs } from '../job-plan.js';

const job = (id, deps = [], state = 'pending') => ({ id, deps, state });

test('ordering includes completed nodes before filtering; readiness uses input states', () => {
  const spec = [job('a', ['z']), job('b'), job('z', [], 'succeeded'), job('c', ['b'])];
  assert.deepEqual(planJobs(spec), { order: ['b', 'c', 'a'], ready: ['a', 'b'], blocked: [] });
  assert.deepEqual(planJobs([...spec].reverse()), planJobs(spec));
});

test('all failed ancestors survive completed intermediates and converging paths', () => {
  assert.deepEqual(planJobs([
    job('z', [], 'failed'), job('a', ['z'], 'failed'),
    job('s', ['a'], 'succeeded'), job('p', ['s', 'z']), job('q', ['p', 'a']),
  ]), { order: [], ready: [], blocked: [
    { id: 'p', causes: ['a', 'z'] }, { id: 'q', causes: ['a', 'z'] },
  ] });
});

test('exact IDs, code-unit ordering, ignored fields, and frozen input', () => {
  const ids = ['constructor', '__proto__', 'é', 'e\u0301', '😀', '\uE000', ' ', 'A', 'a'];
  const spec = Object.freeze(ids.map(id => Object.freeze({
    ...job(id, Object.freeze([])), ignored: { anything: true },
  })));
  const sorted = [...ids].sort();
  assert.deepEqual(planJobs(spec), { order: sorted, ready: sorted, blocked: [] });
  assert.deepEqual(planJobs([job('constructor', ['__proto__']), job('__proto__')]), {
    order: ['__proto__', 'constructor'], ready: ['__proto__'], blocked: [],
  });
});

test('rejects malformed fields, references, duplicates, and cycles in any state', () => {
  const invalid = [null, {}, '[]', [null], [[]], [1], [{}],
    [job('')], [job(1)], [job('a', null)], [job('a', 'b')],
    [job('a', [null])], [job('a', [''])], [job('a', [1])],
    [job('a', [], 'Pending')], [job('a', [], null)],
    [{ id: 'a', deps: [] }], [{ id: 'a', state: 'pending' }],
    [job('a'), job('a')], [job('a', ['b'])],
    [job('a', ['b', 'b']), job('b')], [job('a', ['a'])],
    [job('a', ['b'], 'succeeded'), job('b', ['a'], 'failed')],
    [job('ok'), job('a', ['a'], 'succeeded')],
    new Array(1), [job('a', new Array(1))],
  ];
  for (const spec of invalid) assert.throws(() => planJobs(spec), Error);
});

test('deep graphs do not require recursive traversal', () => {
  const spec = Array.from({ length: 12000 }, (_, i) => job(String(i), i ? [String(i - 1)] : []));
  assert.deepEqual(planJobs(spec), { order: spec.map(j => j.id), ready: ['0'], blocked: [] });
});

test('CLI emits only a plan on success and only stderr with status 2 on errors', () => {
  const dir = mkdtempSync(join(tmpdir(), 'job-plan-'));
  const script = fileURLToPath(new URL('../job-plan.js', import.meta.url));
  const run = args => spawnSync(process.execPath, [script, ...args], { encoding: 'utf8' });
  try {
    const valid = join(dir, 'valid.json');
    const malformed = join(dir, 'malformed.json');
    const invalid = join(dir, 'invalid.json');
    writeFileSync(valid, JSON.stringify([job('雪')]));
    writeFileSync(malformed, '{');
    writeFileSync(invalid, JSON.stringify([job('a', ['a'])]));
    const result = run([valid]);
    assert.equal(result.status, 0);
    assert.equal(result.stderr, '');
    assert.equal(result.stdout, '{"order":["雪"],"ready":["雪"],"blocked":[]}\n');
    for (const args of [[], [valid, valid], [join(dir, 'missing')], [malformed], [invalid], [dir]]) {
      const failure = run(args);
      assert.equal(failure.status, 2);
      assert.equal(failure.stdout, '');
      assert.ok(failure.stderr.length > 0);
    }
    const imported = spawnSync(process.execPath, ['--input-type=module', '-e',
      `import ${JSON.stringify(new URL('../job-plan.js', import.meta.url).href)}`], { encoding: 'utf8' });
    assert.equal(imported.status, 0);
    assert.equal(imported.stdout, '');
    assert.equal(imported.stderr, '');
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});
